#!/usr/bin/env bash
# Command Helper — self-contained installer.
# Generated by scripts/build-installer.sh. Do not edit by hand.
#
# Read this file before you run it. It does not use sudo.
# It installs Command Helper for the current user under ~/.local, then
# downloads the pinned llama.cpp CPU build from GitHub and the pinned
# Qwen3 model from Hugging Face. Both downloads are checked with SHA256.
#
# The program files are embedded further down so this one file is enough.
if [ -z "${BASH_VERSION:-}" ]; then
  printf 'Run this script with bash.\n' >&2
  exit 1
fi
set -euo pipefail

# shellcheck shell=bash
# Shared install logic for Command Helper.
# scripts/build-installer.sh copies this into install.sh and
# command-helper-installer.sh. Edit this file, then rebuild those two.

CH_VERSION=1.0.0
LLAMA_TAG=b11716
LLAMA_RELEASE_BASE="https://github.com/ggml-org/llama.cpp/releases/download/${LLAMA_TAG}"

# Official CPU builds. These are the files the installer downloads.
LLAMA_X64_FILE="llama-${LLAMA_TAG}-bin-ubuntu-x64.tar.gz"
LLAMA_X64_SHA256=8c08b19bee40d118b803d58fd8f6633ba311ce3c7f1f0138262e636f02aa11f0
LLAMA_ARM64_FILE="llama-${LLAMA_TAG}-bin-ubuntu-arm64.tar.gz"
LLAMA_ARM64_SHA256=8cbdc3e5df1e7f37de5c1be4ef93dd4fadea9e0b958f92af6f9c4c84c9882519

# Optional CUDA builds are not downloaded. They are documented in the README.
# x86_64 CUDA 12.8:
#   llama-b11716-bin-ubuntu-cuda-12.8-x64.tar.gz
#   sha256 f467d630fd94d0bcf2a51269f0ecb6dd84125be620daca6497340a93373b2e69
#   cudart-llama-b11716-bin-ubuntu-cuda-12.8-x64.tar.gz
#   sha256 93138d385a12272383bb51bbc7bbe03b6f718136737a500c0c8b4db54cb18d24

# unsloth/Qwen3-4B-Instruct-2507-GGUF at commit a06e946bb6b655725eafa393f4a9745d460374c9
MODEL_FILE="Qwen3-4B-Instruct-2507-Q4_K_M.gguf"
MODEL_SHA256=3605803b982cb64aead44f6c1b2ae36e3acdb41d8e46c8a94c6533bc4c67e597
MODEL_BYTES=2497281120
MODEL_URL="https://huggingface.co/unsloth/Qwen3-4B-Instruct-2507-GGUF/resolve/a06e946bb6b655725eafa393f4a9745d460374c9/${MODEL_FILE}"

# 3.5 GB, decimal, so the model plus a little spare room fit.
CH_DISK_BYTES=3500000000
# MemTotal below this cannot hold the model. About 3.5 GiB.
CH_RAM_MIN_KB=3670016
# Below this we warn. An 8 GB computer usually reports more than 7 GiB.
CH_RAM_WARN_KB=7340032
# yes, no, or empty (not checked yet). Avoids hashing the model twice.
CH_MODEL_STATE=""

ch_say() { printf '\n==> %s\n' "$*"; }
ch_info() { printf '    %s\n' "$*"; }
ch_warn() { printf 'WARNING: %s\n' "$*" >&2; }
ch_die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

ch_print_help() {
  cat << EOF
Command Helper installer (version ${CH_VERSION})

Installs Command Helper for the current user, under ~/.local.
Does not use sudo. Safe to run more than once: finished downloads
are kept when their checksum still matches.

It downloads two things:

  llama.cpp ${LLAMA_TAG} CPU build (about 18 MB on x86_64, about 14 MB on arm64)
    x86_64  ${LLAMA_X64_FILE}
            ${LLAMA_X64_SHA256}
    arm64   ${LLAMA_ARM64_FILE}
            ${LLAMA_ARM64_SHA256}
    from ${LLAMA_RELEASE_BASE}/

  ${MODEL_FILE} (${MODEL_BYTES} bytes, about 2.5 GB)
    ${MODEL_SHA256}
    from Hugging Face (unsloth/Qwen3-4B-Instruct-2507-GGUF)

The CPU build is always what gets installed. A graphics card is not required.

Usage:
  ./install.sh
  ./command-helper-installer.sh
  ./install.sh --help
  ./install.sh --version
EOF
}

ch_sha256_matches() {
  local file=$1 expected=$2 actual
  actual=$(sha256sum -- "$file" | awk '{print $1}')
  [ "$actual" = "$expected" ]
}

ch_asset_for_arch() {
  case "$1" in
    x86_64|amd64)
      printf '%s %s\n' "$LLAMA_X64_FILE" "$LLAMA_X64_SHA256"
      ;;
    aarch64|arm64)
      printf '%s %s\n' "$LLAMA_ARM64_FILE" "$LLAMA_ARM64_SHA256"
      ;;
    *)
      return 1
      ;;
  esac
}

ch_curl() {
  local url=$1 dest=$2
  local -a progress
  if [ -t 1 ]; then
    progress=(--progress-bar)
  else
    progress=(--silent --show-error)
  fi
  # --retry-all-errors is skipped so this still runs on older curl.
  curl --fail --location --retry 5 --retry-delay 2 --retry-connrefused \
    --connect-timeout 30 \
    --user-agent "command-helper/${CH_VERSION}" \
    "${progress[@]}" \
    --output "$dest" \
    "$url"
}

ch_download_verified() {
  local url=$1 dest=$2 expected=$3 label=$4
  if [ -f "$dest" ] && ch_sha256_matches "$dest" "$expected"; then
    ch_info "${label} is already here and the checksum matches."
    return 0
  fi
  mkdir -p "$(dirname "$dest")"
  local partial="${dest}.partial"
  local attempt
  for attempt in 1 2; do
    ch_say "Downloading ${label}"
    ch_info "$url"
    if ! ch_curl "$url" "$partial"; then
      rm -f "$partial"
      ch_die "The download failed for ${label}. Check the network and run the installer again."
    fi
    if ch_sha256_matches "$partial" "$expected"; then
      mv -f "$partial" "$dest"
      ch_info "Checksum OK."
      return 0
    fi
    rm -f "$partial"
    if [ "$attempt" -eq 1 ]; then
      ch_warn "The checksum did not match. Downloading ${label} again."
    fi
  done
  ch_die "The checksum for ${label} did not match after two downloads. Nothing was installed from that file. Run the installer again when the network is stable."
}

ch_free_bytes() {
  local path=$1
  mkdir -p "$path"
  LC_ALL=C df -B1 --output=avail "$path" | awk 'NR==2 {print $1}'
}

ch_memory_class() {
  local kb=$1
  if [ "$kb" -lt "$CH_RAM_MIN_KB" ]; then
    printf 'low\n'
  elif [ "$kb" -lt "$CH_RAM_WARN_KB" ]; then
    printf 'tight\n'
  else
    printf 'ok\n'
  fi
}

ch_format_gb() {
  awk -v kb="$1" 'BEGIN { printf "%.1f GB", kb / 1024 / 1024 }'
}

ch_format_bytes() {
  awk -v b="$1" 'BEGIN { printf "%.1f GB", b / 1000000000 }'
}

ch_check_memory() {
  local kb class
  kb=$(awk '/^MemTotal:/ {print $2}' /proc/meminfo)
  [ -n "$kb" ] || ch_die "Could not read the memory size from /proc/meminfo."
  class=$(ch_memory_class "$kb")
  case "$class" in
    low)
      ch_die "This computer has about $(ch_format_gb "$kb") of memory. Command Helper needs about 4 GB to load the model, and 8 GB is recommended."
      ;;
    tight)
      ch_warn "This computer has about $(ch_format_gb "$kb") of memory. 8 GB is recommended. It can still run, and it may get slow if the system starts using swap."
      ;;
    *)
      ch_info "Memory looks fine ($(ch_format_gb "$kb"))."
      ;;
  esac
}

ch_model_path() {
  printf '%s\n' "${HOME}/.local/share/command-helper/models/${MODEL_FILE}"
}

ch_llama_dir() {
  printf '%s\n' "${HOME}/.local/opt/llama.cpp/llama-${LLAMA_TAG}"
}

ch_prepare_model_file() {
  local path
  path=$(ch_model_path)
  rm -f "${path}.partial"
  if [ ! -f "$path" ]; then
    CH_MODEL_STATE=no
    return 0
  fi
  ch_info "Checking the model file already on disk..."
  if ch_sha256_matches "$path" "$MODEL_SHA256"; then
    CH_MODEL_STATE=yes
    return 0
  fi
  ch_warn "The model file on disk does not match the pinned checksum. Removing it so it can be downloaded again."
  rm -f "$path"
  CH_MODEL_STATE=no
}

ch_model_ready() {
  if [ -z "$CH_MODEL_STATE" ]; then
    ch_prepare_model_file
  fi
  [ "$CH_MODEL_STATE" = yes ]
}

ch_llama_ready() {
  local dir stamp expected name
  dir=$(ch_llama_dir)
  stamp="${dir}/.command-helper-sha256"
  [ -x "${dir}/llama-server" ] && [ -f "$stamp" ] || return 1
  read -r name expected < <(ch_asset_for_arch "$(uname -m)") || return 1
  [ -n "$name" ] || return 1
  [ "$(tr -d '[:space:]' < "$stamp")" = "$expected" ]
}

ch_required_bytes() {
  local model=no llama=no
  if ch_model_ready; then
    model=yes
  fi
  if ch_llama_ready; then
    llama=yes
  fi
  if [ "$model" = yes ] && [ "$llama" = yes ]; then
    printf '20000000\n'
  elif [ "$model" = yes ]; then
    printf '200000000\n'
  else
    printf '%s\n' "$CH_DISK_BYTES"
  fi
}

ch_disk_class() {
  local free=$1 need=$2
  if [ "$free" -lt "$need" ]; then
    printf 'short\n'
  else
    printf 'ok\n'
  fi
}

ch_check_disk() {
  local need free
  ch_prepare_model_file
  need=$(ch_required_bytes)
  free=$(ch_free_bytes "${HOME}/.local")
  [ -n "$free" ] || ch_die "Could not check free disk space."
  if [ "$(ch_disk_class "$free" "$need")" = short ]; then
    ch_die "Need about $(ch_format_bytes "$need") free under the home folder. Found $(ch_format_bytes "$free"). Free some space and run the installer again."
  fi
  ch_info "Free disk space looks fine ($(ch_format_bytes "$free") available)."
}

ch_require_commands() {
  local missing=() cmd
  for cmd in curl tar sha256sum python3 awk install mktemp df; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
      missing+=("$cmd")
    fi
  done
  if [ "${#missing[@]}" -gt 0 ]; then
    ch_die "These programs are missing: ${missing[*]}. Install them with your software manager, then run this installer again."
  fi
}

ch_refuse_root() {
  if [ "$(id -u)" -eq 0 ]; then
    ch_die "Run this as your normal user, without sudo. It installs into the current user's home folder."
  fi
}

ch_preflight() {
  ch_refuse_root
  ch_require_commands
  local arch
  arch=$(uname -m)
  if ! ch_asset_for_arch "$arch" >/dev/null; then
    ch_die "This installer has a CPU build for x86_64 and arm64. This computer reports: ${arch}."
  fi
  ch_info "Architecture: ${arch}."
  ch_check_memory
  ch_check_disk
}

ch_desktop_dir() {
  local d="${HOME}/Desktop"
  local dirs="${HOME}/.config/user-dirs.dirs"
  if [ -f "$dirs" ]; then
    local raw
    raw=$(awk -F= '/^XDG_DESKTOP_DIR=/ {print substr($0, index($0, "=") + 1)}' "$dirs" | head -n 1)
    raw=${raw%\"}
    raw=${raw#\"}
    raw=${raw%\'}
    raw=${raw#\'}
    raw=${raw/\$HOME/$HOME}
    if [ -n "$raw" ]; then
      d=$raw
    fi
  fi
  printf '%s\n' "$d"
}

ch_desktop_exec_value() {
  local path=$1
  local escaped=${path//\\/\\\\}
  escaped=${escaped//\"/\\\"}
  if [[ "$path" == *[[:space:]\"\`\$]* ]]; then
    printf '"%s"\n' "$escaped"
  else
    printf '%s\n' "$path"
  fi
}

ch_render_desktop() {
  local template=$1 dest=$2 exec_path=$3
  local value line key
  value=$(ch_desktop_exec_value "$exec_path")
  mkdir -p "$(dirname "$dest")"
  while IFS= read -r line || [ -n "$line" ]; do
    case "$line" in
      Exec=*|TryExec=*)
        key=${line%%=*}
        printf '%s=%s\n' "$key" "$value"
        ;;
      *)
        printf '%s\n' "$line"
        ;;
    esac
  done < "$template" > "$dest"
}

ch_install_scripts() {
  local src=$1
  local required
  for required in \
    "$src/bin/ask" \
    "$src/bin/command-helper-launch" \
    "$src/uninstall.sh" \
    "$src/share/command-helper.desktop"
  do
    [ -f "$required" ] || ch_die "Missing installer file: ${required}"
  done
  mkdir -p "${HOME}/.local/bin"
  install -m 0755 "$src/bin/ask" "${HOME}/.local/bin/ask"
  install -m 0755 "$src/bin/command-helper-launch" "${HOME}/.local/bin/command-helper-launch"
  install -m 0755 "$src/uninstall.sh" "${HOME}/.local/bin/command-helper-uninstall"
  local pyc
  pyc=$(mktemp)
  python3 -c 'import py_compile, sys; py_compile.compile(sys.argv[1], cfile=sys.argv[2], doraise=True)' \
    "${HOME}/.local/bin/ask" "$pyc"
  rm -f "$pyc"
  ch_info "Installed ask, the launcher, and command-helper-uninstall."
}

ch_install_desktop() {
  local src=$1
  local apps="${HOME}/.local/share/applications"
  local exec_path="${HOME}/.local/bin/command-helper-launch"
  ch_render_desktop "$src/share/command-helper.desktop" "${apps}/command-helper.desktop" "$exec_path"
  chmod 644 "${apps}/command-helper.desktop"
  if command -v update-desktop-database >/dev/null 2>&1; then
    update-desktop-database "$apps" >/dev/null 2>&1 || true
  fi
  ch_info "App menu: ${apps}/command-helper.desktop"
  local desk
  desk=$(ch_desktop_dir)
  if [ -d "$desk" ]; then
    ch_render_desktop "$src/share/command-helper.desktop" "${desk}/command-helper.desktop" "$exec_path"
    chmod 755 "${desk}/command-helper.desktop"
    if command -v gio >/dev/null 2>&1; then
      gio set "${desk}/command-helper.desktop" metadata::trusted true >/dev/null 2>&1 || true
    fi
    ch_info "Desktop icon: ${desk}/command-helper.desktop"
  else
    ch_info "No Desktop folder was found, so only the app menu entry was added."
  fi
}

ch_install_llama() {
  local arch name sha url dir parent tarball version
  arch=$(uname -m)
  read -r name sha < <(ch_asset_for_arch "$arch") || ch_die "No CPU build for ${arch}."
  dir=$(ch_llama_dir)
  parent=$(dirname "$dir")
  if ch_llama_ready; then
    ch_info "llama.cpp ${LLAMA_TAG} is already installed."
    return 0
  fi
  url="${LLAMA_RELEASE_BASE}/${name}"
  mkdir -p "$parent"
  tarball="${parent}/${name}.download"
  ch_download_verified "$url" "$tarball" "$sha" "llama.cpp ${LLAMA_TAG} CPU build"
  rm -rf "$dir"
  tar -xzf "$tarball" -C "$parent"
  rm -f "$tarball"
  [ -x "${dir}/llama-server" ] || ch_die "The llama.cpp archive did not contain llama-server."
  if ! version=$(LD_LIBRARY_PATH="${dir}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}" \
      "${dir}/llama-server" --version 2>&1); then
    printf '%s\n' "$version" >&2
    ch_die "llama-server could not run. The message above may say which library is missing."
  fi
  printf '%s\n' "$sha" > "${dir}/.command-helper-sha256"
  ch_info "$version"
}

ch_install_model() {
  local dest
  dest=$(ch_model_path)
  if [ "$CH_MODEL_STATE" = yes ]; then
    ch_info "language model (${MODEL_FILE}, about 2.5 GB) is already here and the checksum matches."
    return 0
  fi
  ch_download_verified "$MODEL_URL" "$dest" "$MODEL_SHA256" "language model (${MODEL_FILE}, about 2.5 GB)"
  CH_MODEL_STATE=yes
}

ch_append_path_snippet() {
  local file=$1
  local begin="# >>> command-helper >>>"
  if [ -f "$file" ] && grep -qF "$begin" "$file"; then
    return 0
  fi
  mkdir -p "$(dirname "$file")"
  if [ -s "$file" ]; then
    printf '\n' >> "$file"
  fi
  cat >> "$file" << 'EOF'
# >>> command-helper >>>
# Added by Command Helper. Removes cleanly with command-helper-uninstall.
case ":$PATH:" in
  *:"$HOME/.local/bin":*) ;;
  *) export PATH="$HOME/.local/bin:$PATH" ;;
esac
# <<< command-helper <<<
EOF
}

ch_ensure_user_path() {
  local shell_name
  shell_name=$(basename "${SHELL:-bash}")
  if [ -f "${HOME}/.bashrc" ] || [ "$shell_name" = "bash" ] || [ "$shell_name" = "sh" ]; then
    ch_append_path_snippet "${HOME}/.bashrc"
  fi
  if [ -f "${HOME}/.profile" ]; then
    ch_append_path_snippet "${HOME}/.profile"
  fi
  if [ -f "${HOME}/.zshrc" ] || [ "$shell_name" = "zsh" ]; then
    ch_append_path_snippet "${HOME}/.zshrc"
  fi
  if ! grep -qF "# >>> command-helper >>>" "${HOME}/.bashrc" 2>/dev/null \
    && ! grep -qF "# >>> command-helper >>>" "${HOME}/.profile" 2>/dev/null \
    && ! grep -qF "# >>> command-helper >>>" "${HOME}/.zshrc" 2>/dev/null; then
    ch_append_path_snippet "${HOME}/.bashrc"
  fi
  case ":${PATH}:" in
    *":${HOME}/.local/bin:"*)
      ch_info "PATH already includes ~/.local/bin in this terminal."
      ;;
    *)
      ch_info "Open a new terminal window so it can find the ask command."
      ;;
  esac
}

ch_nvidia_present() {
  if [ -r /proc/driver/nvidia/version ]; then
    return 0
  fi
  if ! command -v nvidia-smi >/dev/null 2>&1; then
    return 1
  fi
  if command -v timeout >/dev/null 2>&1; then
    timeout 5 nvidia-smi -L >/dev/null 2>&1
  else
    nvidia-smi -L >/dev/null 2>&1
  fi
}

ch_finish() {
  ch_say "Command Helper is ready"
  if ch_nvidia_present; then
    ch_warn "An NVIDIA graphics card was detected. The CPU build is what got installed, and that is what Command Helper uses. A graphics card is optional. See \"Optional: NVIDIA graphics card\" in the README."
  fi
  cat << 'EOF'

Open a new terminal window and try:

    ask show me my disk space

The app menu has an entry named "Command Helper" as well. The desktop
icon is there when a Desktop folder exists.

The first answer takes a few extra seconds while the model loads.
After 15 minutes with no questions, the model unloads to free memory.
The next question loads it again.

To remove Command Helper later, run:

    command-helper-uninstall

EOF
}

ch_install_all() {
  local src=$1
  umask 022
  ch_say "Command Helper ${CH_VERSION}"
  ch_info "Installing for the current user. This does not use sudo."
  ch_info "Pinned to llama.cpp ${LLAMA_TAG} (CPU) and ${MODEL_FILE}."
  ch_preflight
  ch_say "Installing the program"
  ch_install_scripts "$src"
  ch_install_desktop "$src"
  ch_say "Installing llama.cpp"
  ch_install_llama
  ch_say "Installing the language model"
  ch_install_model
  ch_say "Updating PATH"
  ch_ensure_user_path
  ch_finish
}

ch_dispatch() {
  local src=$1
  shift
  case "${1:-}" in
    -h|--help)
      ch_print_help
      ;;
    -V|--version)
      printf '%s\n' "$CH_VERSION"
      ;;
    "")
      ch_install_all "$src"
      ;;
    *)
      ch_die "Unknown option: $1 (try --help)"
      ;;
  esac
}

# Program files embedded so this installer is a single download.
ch_extract_payloads() {
  local dest=$1
  mkdir -p "$(dirname "$dest/bin/ask")"
  cat > "$dest/bin/ask" << 'CH_EMBED_ASK'
#!/usr/bin/env python3
"""ask - plain-English to Linux command helper (local, offline).

Usage:
  ask <what you want to do>     one request
  ask                           interactive loop (type 'quit' to leave)
  ask --print <request>         only show the suggestion, never offer to run it
  ask --version                 print the version

Runs Qwen3-4B-Instruct locally through llama.cpp (llama-server on
127.0.0.1 only). Nothing leaves this computer. Nothing you type is saved.
"""
import json
import os
import re
import subprocess
import sys
import time
import urllib.request

VERSION = "1.0.0"

HOME = os.path.expanduser("~")
LLAMA_DIR = os.environ.get(
    "COMMAND_HELPER_LLAMA_DIR",
    os.path.join(HOME, ".local/opt/llama.cpp/llama-b11716"),
)
MODEL = os.environ.get(
    "COMMAND_HELPER_MODEL",
    os.path.join(
        HOME,
        ".local/share/command-helper/models/Qwen3-4B-Instruct-2507-Q4_K_M.gguf",
    ),
)
STATE_DIR = os.path.join(HOME, ".local/state/command-helper")
HOST, PORT = "127.0.0.1", 8742
BASE = f"http://{HOST}:{PORT}"

SYSTEM_PROMPT = (
    "You are a Linux command helper. Reply with one bash command "
    "(or a short && chain) and a one-line plain-English explanation. No chit-chat.\n"
    "Use exactly this format and nothing else:\n"
    "COMMAND: <the command on one line>\n"
    "EXPLANATION: <one short plain-English sentence>"
)

TTY = sys.stdout.isatty() and not os.environ.get("NO_COLOR")


def c(code, s):
    return f"\033[{code}m{s}\033[0m" if TTY else s


RED_BOLD = lambda s: c("1;37;41", s)
RED = lambda s: c("1;31", s)
GREEN = lambda s: c("1;32", s)
CYAN = lambda s: c("1;36", s)
DIM = lambda s: c("2", s)

# A match asks the user to type yes. This is a guardrail, not proof a command is safe.
DANGER = [
    (r"(^|[\s;&|(`$])sudo\b", "uses sudo (runs as administrator/root)"),
    (r"(^|[\s;&|(`$])(su|doas|pkexec)\b", "switches to another user / root"),
    (r"(^|[\s;&|(`$])rm\b", "deletes files (rm) - there is no recycle bin"),
    (r"(^|[\s;&|(`$])rmdir\b", "deletes folders"),
    (r"(^|[\s;&|(`$])dd\b", "dd writes raw data and can wipe disks"),
    (r"(^|[\s;&|(`$])mkfs(\.\w+)?\b", "formats a disk/partition (erases it)"),
    (r"(^|[\s;&|(`$])(fdisk|sfdisk|cfdisk|gdisk|sgdisk|parted|gparted|wipefs|mkswap|cryptsetup|lvremove|vgremove|pvremove|mdadm)\b",
     "disk partition / encryption tool"),
    (r"(^|[\s;&|(`$])shred\b", "permanently destroys file contents"),
    (r"(^|[\s;&|(`$])truncate\b", "can empty files"),
    (r"(^|[\s;&|(`$])chmod\b[^;&|]*\s-[a-zA-Z]*R", "changes permissions recursively (chmod -R)"),
    (r"(^|[\s;&|(`$])chown\b", "changes file ownership (chown)"),
    (r"(^|[\s;&|(`$])systemctl\b", "controls system services (systemctl)"),
    (r"(^|[\s;&|(`$])(apt|apt-get|dpkg|snap)\b[^;&|]*\b(remove|purge|autoremove|-r|-P)\b", "removes software"),
    (r"(^|[\s;&|(`$])(dnf|yum|zypper)\b[^;&|]*\b(remove|erase)\b", "removes software"),
    (r"(^|[\s;&|(`$])pacman\b[^;&|]*\s-[A-Za-z]*R", "removes software (pacman)"),
    (r"(^|[\s;&|(`$])(shutdown|reboot|poweroff|halt)\b", "shuts down / restarts the computer"),
    (r"(^|[\s;&|(`$])(kill|pkill|killall)\b", "stops running programs"),
    (r"(^|[\s;&|(`$])mv\b", "moves/renames files (can overwrite)"),
    (r"(^|[\s;&|(`$])crontab\b[^;&|]*\s-r", "deletes scheduled tasks"),
    (r"(curl|wget)\b[^|]*\|\s*(sudo\s+)?(ba|z|da)?sh\b", "downloads and runs a script from the internet"),
    (r":\(\)\s*\{", "fork bomb"),
    (r"(^|[\s;&|(`$])tee\b", "writes into files (tee)"),
]


def risks(cmd):
    found = [why for pat, why in DANGER if re.search(pat, cmd)]
    # any output redirection (> or >>) other than harmless stderr/null forms
    stripped = re.sub(r"\d?>&\d|&?>\s*/dev/null|\d>\s*/dev/null", "", cmd)
    if ">" in re.sub(r"'[^']*'|\"[^\"]*\"", "", stripped):
        found.append("writes/overwrites a file with > or >>")
    return found


def wants_cuda():
    """True only when the user opts in. The default is the CPU."""
    choice = os.environ.get("COMMAND_HELPER_BACKEND", "").strip().lower()
    if not choice:
        path = os.path.join(HOME, ".config", "command-helper", "backend")
        try:
            with open(path, encoding="utf-8") as handle:
                text = handle.read().strip().lower()
        except OSError:
            text = ""
        if text:
            choice = text.splitlines()[0].strip()
    if not choice:
        return False
    return choice.split()[0] == "cuda"


def server_argv(exe, use_cuda):
    argv = [
        exe, "-m", MODEL, "--host", HOST, "--port", str(PORT),
        "-c", "4096", "-np", "1", "-t", "8",
    ]
    if use_cuda:
        argv.extend(["-ngl", "99"])
    else:
        argv.extend(["--device", "none", "-ngl", "0"])
    argv.extend(["--reasoning", "off", "--sleep-idle-seconds", "900", "--no-webui"])
    return argv


def server_env(base, use_cuda):
    env = dict(base)
    # CPU only by default: hide GPUs so llama.cpp does not try to use one.
    # Opt in to NVIDIA CUDA by writing "cuda" in ~/.config/command-helper/backend.
    env["LD_LIBRARY_PATH"] = LLAMA_DIR + ":" + env.get("LD_LIBRARY_PATH", "")
    env["HIP_VISIBLE_DEVICES"] = "-1"
    env["ROCR_VISIBLE_DEVICES"] = "-1"
    if not use_cuda:
        env["CUDA_VISIBLE_DEVICES"] = ""
    return env


def server_ok():
    try:
        with urllib.request.urlopen(BASE + "/health", timeout=2) as response:
            return response.status == 200
    except Exception:
        return False


def start_server():
    if server_ok():
        return True
    exe = os.path.join(LLAMA_DIR, "llama-server")
    if not (os.path.exists(exe) and os.path.exists(MODEL)):
        print(RED("Command helper model or llama.cpp not found. Expected:\n  " + exe + "\n  " + MODEL))
        return False
    os.makedirs(STATE_DIR, exist_ok=True)
    use_cuda = wants_cuda()
    env = server_env(os.environ, use_cuda)
    argv = server_argv(exe, use_cuda)
    log_path = os.path.join(STATE_DIR, "llama-server.log")
    log = open(log_path, "ab")
    try:
        subprocess.Popen(
            argv,
            stdin=subprocess.DEVNULL,
            stdout=log,
            stderr=log,
            env=env,
            start_new_session=True,
        )
    finally:
        log.close()
    if use_cuda:
        sys.stderr.write(DIM("(using the NVIDIA CUDA opt-in)\n"))
    sys.stderr.write(DIM("(starting the local model, first time takes a few seconds...)\n"))
    for _ in range(240):
        if server_ok():
            return True
        time.sleep(0.25)
    print(RED("The local model did not start. See " + log_path))
    return False


def ask_model(request):
    body = json.dumps({
        "messages": [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": request},
        ],
        "temperature": 0.1,
        "max_tokens": 200,
        "stream": False,
    }).encode()
    req = urllib.request.Request(
        BASE + "/v1/chat/completions",
        data=body,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=180) as response:
        out = json.load(response)
    return out["choices"][0]["message"].get("content") or ""


def parse(text):
    text = re.sub(r"<think>.*?</think>", "", text, flags=re.S).replace("<think>", "").strip()
    cmd = expl = ""
    match = re.search(r"COMMAND:\s*(.+)", text)
    if match:
        cmd = match.group(1).strip()
    match = re.search(r"EXPLANATION:\s*(.+)", text)
    if match:
        expl = match.group(1).strip()
    if not cmd:
        match = re.search(r"```(?:bash|sh)?\s*\n?(.+?)\n?```", text, re.S)
        if match:
            cmd = match.group(1).strip().splitlines()[0]
    if not cmd and text:
        cmd = text.splitlines()[0]
    cmd = cmd.strip().strip("`").strip()
    if cmd.startswith("$ "):
        cmd = cmd[2:]
    return cmd, expl


def handle(request, allow_run=True):
    if not start_server():
        return
    started = time.time()
    try:
        cmd, expl = parse(ask_model(request))
    except Exception as exc:
        print(RED(f"Could not get an answer from the local model: {exc}"))
        return
    elapsed = time.time() - started
    if not cmd:
        print(RED("No command came back. Try rephrasing."))
        return
    print()
    print(CYAN("Command:     ") + cmd)
    print(CYAN("Explanation: ") + (expl or "(none given)"))
    print(DIM(f"({elapsed:.1f}s)"))
    if not allow_run:
        return
    danger = risks(cmd)
    try:
        if danger:
            print()
            print(RED_BOLD(" WARNING: this command can change or delete things, or needs root "))
            for why in danger:
                print(RED("  - " + why))
            print(RED("Read it carefully. If you are not sure, do NOT run it."))
            ans = input(RED("Type 'yes' in full to run it, anything else cancels: ")).strip()
            ok = ans == "yes"
        else:
            ans = input("Run it? [y/N] ").strip().lower()
            ok = ans in ("y", "yes")
    except EOFError:
        ok = False
        print()
    if not ok:
        print(DIM("Not run."))
        return
    print(DIM("-" * 60))
    # Runs in your normal terminal; if the command uses sudo, sudo asks for your
    # password itself. This program never sees or stores it.
    sys.stdout.flush()
    rc = subprocess.call(["bash", "-c", cmd])
    print(DIM("-" * 60))
    print(GREEN("Done.") if rc == 0 else RED(f"Finished with exit code {rc}."))


def loop():
    try:
        import readline  # arrow keys/editing; history is kept in memory only
    except Exception:
        pass
    print(GREEN("Command Helper") + " - describe what you want to do in plain English.")
    print(DIM("Type 'quit' (or press Ctrl+D) to leave. Nothing you type is saved."))
    while True:
        try:
            req = input("\n" + CYAN("ask> ")).strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if not req:
            continue
        if req.lower() in ("quit", "exit", "q", "bye"):
            break
        try:
            handle(req)
        except KeyboardInterrupt:
            print(DIM("\n(cancelled)"))


def main():
    args = sys.argv[1:]
    if args and args[0] in ("-h", "--help"):
        print(__doc__.strip())
        return
    if args and args[0] in ("-V", "--version"):
        print(VERSION)
        return
    allow_run = True
    if args and args[0] in ("-p", "--print"):
        allow_run = False
        args = args[1:]
    if args:
        try:
            handle(" ".join(args), allow_run)
        except KeyboardInterrupt:
            print(DIM("\n(cancelled)"))
    else:
        loop()


if __name__ == "__main__":
    main()
CH_EMBED_ASK
  chmod 755 "$dest/bin/ask"
